    "bon_df['views_per_like'] = bon_df.avg_views / bon_df.avg_likes.replace(0, float('nan'))\n",
    "\n",
    "bon_df['likes_pct'] = bon_df.avg_likes / bon_df.follower_count.replace(0, float('nan')) * 100\n",
    "\n",
    "bon_df['comment_like_ratio_pct'] = bon_df.avg_comments / bon_df.avg_likes.replace(0, float('nan')) * 100\n",
    "\n",
    "bon_df[['views_per_like', 'likes_pct', 'comment_like_ratio_pct']].head()"
